10→      "packages/drive/routes/drive.php — по P6-design#Routes (DRIVE и Uploads), имена vaulter.v1.*, стек authenticated, uploads + throttle:vaulter-uploads; без ResolveVaulterRouteParameters/SubstituteBindings.",
